local TagType = {
    Discount = 1, -- 折扣
    Recommend = 2, -- 推荐
    All = 3, -- 折扣+推荐
}

------------ define ------------

--- from: Assets/BundleResources/Prefabs/Activity/ActivityRegressionRewardPopUpDialog.prefab > name: OverseaMallGiftPackNode
---@class RegressionGiftPackNode
---@field Env                            RegressionGiftPackNode
---@field controller                        Engine.Modules.LuaBehaviour
---@field CatQuality                        UnityEngine.RectTransform
---@field CommonGoodsListLight            UnityEngine.RectTransform
