local RegressionGiftPackNode = Class('RegressionGiftPackNode')

function RegressionGiftPackNode:__init()
    self.cellData = nil
end

function RegressionGiftPackNode:__delete()
    self.cellData = nil
end

function RegressionGiftPackNode:Awake()
    ---@type CommonGoodsListLight
    self.goodsListScr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    SetButtonAction(self.BtnNode, Bind(self, self.OnClickHandler))
end

--region handler
function RegressionGiftPackNode:OnClickHandler()
    if isNull(self.cellData) then
        return
    end

    -- 免费商品
    if checkInt(self.cellData.isFree) == 1 then
        if checkNumber(self.cellData.currentStock) <= 0 then
            GameUtils.Toast(localize("商品已售罄"))
        else
            if self.buyCb then
                self.buyCb(self.cellData, self.position)
            end
        end
        return
    end
    local consumeGoodsId = nil
    local isPayMoney = true
    local price = self.cellData.price
    if self:IsGoodExchange() then
        isPayMoney = false
        local currencyData = self:GetCurrencyData()
        consumeGoodsId = currencyData.currency
        price = currencyData.num
    end
    -- 不免费商品
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId = self.cellData.icon,
        consumeNum = price,
        consumeGoodsId = consumeGoodsId,
        maxBuyNum = self.cellData.currentStock,
        rewards = self.cellData.rewards,
        isShowNum = true,
        isPayMoney = isPayMoney,
        channelProductId = self.cellData.channelProductId,
        isBackDialog = true,
        --isCloseSDKSecondConfirm = true,
        buyCb = function()
            if self:IsGoodExchange() then
                local currencyData = self:GetCurrencyData()
                local ActivityConstants = import("Game.Activity.ActivityConstants")
                ----请求兑换的逻辑
                GameUtils.Request(Interfaces.OverseaRegressRegressGiftBuy, {
                    productId = self.cellData.productId,
                    currency = checkInt(currencyData.currency),
                    type = ActivityConstants.ActivityType.RegressTask,
                    num = 1,
                }, function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local oneReawards = response.data.rewards or {}
                        local rewards = clone(oneReawards)
                        rewards[#rewards + 1] = {
                            goodsId = currencyData.currency,
                            num = -currencyData.num,
                        }
                        GoodsUtils.DrawRewards(rewards)
                        if #oneReawards > 0 then
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = oneReawards, cb = function()
                                Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_PAY })
                            end } })
                        else
                            Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_PAY })
                        end
                    end
                end)
            else
                local payInfo = {
                    productId = self.cellData.productId,
                    channelProductId = self.cellData.channelProductId,
                    payAmount = self.cellData.price
                }
                SDKService:GetInstance():PayMoney({
                    productId = self.cellData.productId,
                    channelProductId = self.cellData.channelProductId,
                    productDesc = self._productVo.desc,
                    payAmount = self.cellData.price,
                    data = payInfo
                })
            end
        end
    } })
end
--endregion handler
--region public
function RegressionGiftPackNode:Refresh(productNode, position, onBuyCb)
    self.buyCb = onBuyCb
    self.position = position
    self.cellData = productNode
    ---@type GoodsVo
    self._productVo = GoodsConfMgr:GetInstance():GetGoodsVoById(productNode.icon)
    self:RefreshUI()
end

function RegressionGiftPackNode:IsGoodExchange()
    local isFree = checkInt(self.cellData.isFree)
    local prices = self.cellData.prices or {}
    if isFree == 0 and table.count(prices) > 0 then
        return true
    end
    return false
end

function RegressionGiftPackNode:GetCurrencyData()
    local t = {}
    for k, v in pairs(self.cellData.prices) do
        t.currency = k
        t.num = v.current
        t.goodsPath = GoodsConfMgr:GetInstance():GetPhotoPathById(k)
        break
    end
    return t
end

--endregion public

--region private
function RegressionGiftPackNode:RefreshUI()
    CfUtils.SetActive(self.TimerGroup, false)

    -- 商品基本信息
    CfUtils.FillImage(self.ImgIcon, self._productVo.photoPath)

    -- 品质
    CfUtils.SetUISwitchImage(self.CatQuality, self._productVo.quality)

    -- 价格
    if checkNumber(self.cellData.isFree) == 1 then
        CfUtils.SetActive(self.FreeGroup, true)
        CfUtils.SetActive(self.PriceGroup, false)
        CfUtils.SetActive(self.redPoint, checkNumber(self.cellData.currentStock) > 0)
    else
        CfUtils.SetActive(self.FreeGroup, false)
        CfUtils.SetActive(self.PriceGroup, true)
        if self:IsGoodExchange() then
            local currencyData = self:GetCurrencyData()
            local goodsPath = currencyData.goodsPath
            KTool.SetActive(self.CurrencyImgIcon.gameObject, true)
            CfUtils.FillText(self.CurPrice:Find("TextNumber"), currencyData.num)
            CfUtils.FillImage(self.CurrencyImgIcon, currencyData.goodsPath)
        else
            KTool.SetActive(self.CurrencyImgIcon.gameObject, false)
            CfUtils.FillText(self.CurPrice:Find("TextNumber"), CfUtils.GetDisplayPrice(self.cellData.price, self.cellData.channelProductId))
        end
    end

    -- 商城库存
    CfUtils.FillText(self.TxtNumber, self.cellData.currentStock)
    CfUtils.SetActive(self.SellOutGroup, checkNumber(self.cellData.currentStock) == 0)
    CfUtils.SetUISwitchImage(self.GiftPackQuality, checkNumber(self.cellData.currentStock) == 0 and 1 or 2)

    -- 折扣角标
    local tabType = checkInt(self.cellData.iconId)
    if tabType == TagType.Discount then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self.cellData.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    elseif tabType == TagType.Recommend then
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
    elseif tabType == TagType.All then
        CfUtils.FillText(self.DiscountTxtNumber, string.format('%s<size=18>%%</size>', checkInt(self.cellData.iconTitle) * 100))
        CfUtils.SetActive(self.DiscountGroup, true)
        CfUtils.SetActive(self.ActivityTabelGroup, true)
    else
        CfUtils.SetActive(self.DiscountGroup, false)
        CfUtils.SetActive(self.ActivityTabelGroup, false)
    end

    ---@type GiftGoodsVo
    -- local giftGoodsVo = CfUtils.GetCfVo(AutoIds.IdSetting111, "GiftGoodsVo", self.cellData.icon)
    self.goodsListScr:FreshBaseUI(self.cellData.rewards)
end
--endregion private
function RegressionGiftPackNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return RegressionGiftPackNode